      { "source": "checkout-service", "target": "kafka", "protocol": "TCP" },
      { "source": "shipping-service", "target": "quote-service", "protocol": "HTTP" },
      { "source": "recommendation-service", "target": "product-catalog-service", "protocol": "gRPC" },
